import org.jsoup.Connection;
import org.junit.Assert;
import org.junit.Test;

import java.io.UnsupportedEncodingException;
import java.net.URL;

public class UrlBuilderTest {

    @Test
    public void UrlBuilder_ValidInput_Test() throws Exception {
        URL inputUrl = new URL("http://www.test.com");
        UrlBuilder builder = new UrlBuilder(inputUrl);
        Assert.assertNotNull(builder);
    }

    @Test(expected = NullPointerException.class)
    public void UrlBuilder_NullInput_Test() {
        UrlBuilder builder = new UrlBuilder(null);
    }

    @Test
    public void build_ValidUrl_Test() throws Exception {
        URL inputUrl = new URL("http://www.test.com");
        UrlBuilder builder = new UrlBuilder(inputUrl);
        URL outputUrl = builder.build();
        Assert.assertEquals(inputUrl, outputUrl);
    }

    @Test(expected = IllegalArgumentException.class)
    public void build_InvalidUrl_Test() throws Exception {
        URL inputUrl = new URL("http://this is not a url");
        UrlBuilder builder = new UrlBuilder(inputUrl);
        builder.build();
    }

    @Test
    public void appendKeyVal_ValidInput_Test() throws Exception {
        URL inputUrl = new URL("http://www.test.com");
        UrlBuilder builder = new UrlBuilder(inputUrl);
        Connection.KeyVal keyVal = Connection.KeyVal.create("key", "value");
        builder.appendKeyVal(keyVal);
        URL expectedUrl = new URL("http://www.test.com?key=value");
        Assert.assertEquals(expectedUrl, builder.build());
    }

    @Test(expected = UnsupportedEncodingException.class)
    public void appendKeyVal_InvalidInput_Test() throws Exception {
        URL inputUrl = new URL("http://www.test.com");
        UrlBuilder builder = new UrlBuilder(inputUrl);
        Connection.KeyVal keyVal = Connection.KeyVal.create("key", "this is not valid");
        builder.appendKeyVal(keyVal);
    }
}
